/* FreeDV engine for Ham Radio Web Studio — the real thing.
   This file embeds libcodec2 1.2.0 (David Rowe VK5DGR and contributors,
   LGPL-2.1, https://github.com/drowe67/codec2) compiled to WebAssembly
   with clang/wasi-libc. It provides bit-true FreeDV 1600 / 700C / 700D /
   700E TX and RX via freedv_api. See the studio README for license notes
   and how to rebuild this artifact from source. */
(function (root, factory) {
  if (typeof module !== "undefined" && module.exports) module.exports = factory();
  else root.FreeDVEngine = factory();
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";
  const WASM_B64 = "";

  function b64bytes(s) {
    if (typeof Buffer !== "undefined") return Buffer.from(s, "base64");
    const bin = atob(s);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  let enginePromise = null;

  async function init() {
    const bytes = b64bytes(WASM_B64);
    const shim = new Proxy({}, {
      get: (t, name) => {
        if (name === "proc_exit") return c => { throw new Error("wasm exit " + c); };
        return () => 0;                       /* fd_*, environ_*, clocks… */
      }
    });
    const { instance } = await WebAssembly.instantiate(bytes, {
      wasi_snapshot_preview1: shim
    });
    const E = instance.exports;
    E._initialize();
    const H16 = () => new Int16Array(E.memory.buffer);

    const MODES = { fdv1600: 0, fdv700c: 6, fdv700d: 7, fdv700e: 13 };

    class Handle {
      constructor(modeKey) {
        this.h = E.fdv_open(MODES[modeKey]);
        if (!this.h) throw new Error("freedv_open failed for " + modeKey);
        this.nSpeech = E.fdv_n_speech(this.h);
        this.nNomModem = E.fdv_n_nom_modem(this.h);
        this.spPtr = E.fdv_speech_buf(this.h) >> 1;
        this.mdPtr = E.fdv_modem_buf(this.h) >> 1;
        this._q = new Int16Array(0);
      }
      /* Float32 speech (8 kHz), exactly nSpeech -> Float32 modem audio */
      txFrame(speechF32) {
        const heap = H16();
        for (let i = 0; i < this.nSpeech; i++)
          heap[this.spPtr + i] = Math.max(-32768, Math.min(32767,
            Math.round(speechF32[i] * 27000)));
        const n = E.fdv_tx(this.h);
        const heap2 = H16();
        const out = new Float32Array(n);
        for (let i = 0; i < n; i++) out[i] = heap2[this.mdPtr + i] / 32768;
        return out;
      }
      /* Float32 modem audio (8 kHz) chunks in, decoded speech out */
      rxChunk(modemF32) {
        const add = new Int16Array(modemF32.length);
        for (let i = 0; i < modemF32.length; i++)
          add[i] = Math.max(-32768, Math.min(32767, Math.round(modemF32[i] * 32767)));
        const q = new Int16Array(this._q.length + add.length);
        q.set(this._q); q.set(add, this._q.length);
        this._q = q;
        const voice = [];
        let frames = 0;
        for (;;) {
          const nin = E.fdv_nin(this.h);
          if (this._q.length < nin) break;
          const heap = H16();
          for (let i = 0; i < nin; i++) heap[this.mdPtr + i] = this._q[i];
          this._q = this._q.slice(nin);
          const nout = E.fdv_rx(this.h);
          frames++;
          const heap2 = H16();
          for (let i = 0; i < nout; i++) voice.push(heap2[this.spPtr + i] / 32768);
        }
        return {
          voice: Float32Array.from(voice),
          frames,
          sync: E.fdv_sync(this.h),
          snr: E.fdv_snr_x10(this.h) / 10
        };
      }
      squelch(en, thresh) { E.fdv_squelch(this.h, en ? 1 : 0, Math.round(thresh * 10)); }
      close() { E.fdv_close(this.h); }
    }

    return { open: (modeKey) => new Handle(modeKey), modes: Object.keys(MODES) };
  }

  return function FreeDVEngine() {
    if (!enginePromise) enginePromise = init();
    return enginePromise;
  };
});
